css:
.br { display: flex; flex-wrap: wrap; gap: .75rem; margin-top: 2rem; }
.br a { text-decoration: none; }
.br__btn { display: inline-flex; align-items: center; min-height: 48px; padding: .7rem 1.4rem; border: 2px solid currentColor; border-radius: 999px; font-weight: 700; font-size: 1rem; color: var(--os-color-heading); }
.br__btn--p { border-color: transparent; background: linear-gradient(90deg, var(--bff-btn-a, #a7c25a), var(--bff-btn-b, #f2cb4a)); color: #15261a; }
.br__btn:hover { background-color: color-mix(in srgb, var(--os-color-text) 8%, transparent); }
.br__btn--p:hover { filter: saturate(1.15); }
